/bin/bash -lc "python3 -c 'def si(n,s,c): return {i for i in range(n) if i%c==s-1}
def sn(ns,s,c,a):
    return si(len(ns),s,c) if a and max(a.values())"'!=c else {i for i,n in enumerate(ns) if a.get(n,(i%c)+1)==s}
for n in range(8):
    ns=[f"t{i}" for i in range(n)]
    for c in range(1,5):
        sh=[sn(ns,s,c,{}) for s in range(1,c+1)]; assert set().union(*sh) == set(range(n)); assert sum(map(len, sh)) == n
        if n:
            a={nid:(i%c)+1 for i,nid in enumerate(ns)}; a[ns[0]]=c
            sh=[sn(ns,s,c,a) for s in range(1,c+1)]; assert set().union(*sh)==set(range(n)); assert sum(map(len,sh))==n
        bad={"t0":c+1} if n else {"x":c+1}
        sh=[sn(ns,s,c,bad) for s in range(1,c+1)]; assert sh == [si(n,s,c) for s in range(1,c+1)]
print("ok")'"'"

